import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        long c = Long.parseLong(st.nextToken());

        // Let x = bonds(1,2), y = bonds(2,3), z = bonds(3,1)
        // Equations:
        // x + z = a
        // x + y = b
        // y + z = c
        //
        // Solve:
        // x = (a + b - c) / 2
        // y = (b + c - a) / 2
        // z = (a + c - b) / 2

        long xNum = a + b - c;
        long yNum = b + c - a;
        long zNum = a + c - b;

        // Check non-negative and even
        if (xNum < 0 || yNum < 0 || zNum < 0 ||
            (xNum & 1L) != 0 || (yNum & 1L) != 0 || (zNum & 1L) != 0) {
            System.out.println("Impossible");
            return;
        }

        long x = xNum / 2;
        long y = yNum / 2;
        long z = zNum / 2;

        // Ensure all bonds are non-negative
        if (x < 0 || y < 0 || z < 0) {
            System.out.println("Impossible");
            return;
        }

        System.out.println(x + " " + y + " " + z);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        long a = fs.nextLong();
        long b = fs.nextLong();
        long c = fs.nextLong();

        // Let x = bonds between 1 and 2
        //     y = bonds between 2 and 3
        //     z = bonds between 3 and 1
        //
        // Equations:
        // x + z = a
        // x + y = b
        // y + z = c
        //
        // Solve:
        // x = (a + b - c) / 2
        // y = (b + c - a) / 2
        // z = (c + a - b) / 2

        long xNum = a + b - c;
        long yNum = b + c - a;
        long zNum = c + a - b;

        // Check parity and non-negativity
        if ((xNum & 1L) != 0 || (yNum & 1L) != 0 || (zNum & 1L) != 0) {
            System.out.println("Impossible");
            return;
        }

        long x = xNum / 2;
        long y = yNum / 2;
        long z = zNum / 2;

        if (x < 0 || y < 0 || z < 0) {
            System.out.println("Impossible");
            return;
        }

        // Ensure each atom has at least one bond
        if (a <= 0 || b <= 0 || c <= 0) {
            System.out.println("Impossible");
            return;
        }

        // Final verification (defensive)
        if (x + z != a || x + y != b || y + z != c) {
            System.out.println("Impossible");
            return;
        }

        System.out.println(x + " " + y + " " + z);
    }

    // Simple fast scanner
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

